using System;
using System.Collections.Generic;
using UnityEngine.UIElements;
namespace MassiveArmy.Planetary {
    public sealed partial class PlanetRtsHud {
        int deathPage;
        void DeathDetails(VisualElement parent,DeathRecord death){var simulation=world.Civilisation;Label(parent,death.name+" · age "+(int)death.age,"subheading").name="civic-deceased-name";Label(parent,SettlementCrimeView.Cause(death.cause)+" · "+simulation.CivicDate(death.time),"body");Label(parent,!death.discovered?"Undiscovered body · observer information":death.interred?"Buried · "+simulation.CivicDate(death.burialAt):death.ceremonyAt>0?"Funeral in progress":death.delivered?"At the graveyard · awaiting funeral":death.collected?"In transit to graveyard":death.hearse!=0?"Hearse dispatched":"Awaiting a graveyard and hearse","muted");if(death.policeHonours)Label(parent,"POLICE HONOURS · due "+simulation.CivicDate(death.ceremonyDue),"muted");}
        void HearseContext(VisualElement parent,CargoVehicleState hearse){Label(parent,"HEARSE","heading").name="civic-hearse-title";Label(parent,hearse.phase.ToString()+" · "+(hearse.navigationStatus==3?"Road route blocked":"Road transport"),"body");foreach(var c in world.Settlements)if(c!=null){var death=c.deaths.Find(d=>d.id==hearse.funeralDeath);if(death!=null){DeathDetails(parent,death);break;}}}
        void RecentDeaths(VisualElement parent,ColonyState c,int pageSize){var visible=c.deaths.FindAll(d=>Observer||d.discovered);Label(parent,"RECENT DEATHS · "+visible.Count,"subheading").name="civic-death-register";if(visible.Count==0){Label(parent,"No deaths recorded","muted");return;}int max=Math.Max(0,(visible.Count-1)/pageSize);deathPage=Math.Min(deathPage,max);var controls=new VisualElement();controls.AddToClassList("row");parent.Add(controls);Button(controls,"NEWER",()=>{deathPage=Math.Max(0,deathPage-1);world.NotifyChanged();nextCivilisationRefresh=0;});Button(controls,"OLDER",()=>{deathPage=Math.Min(max,deathPage+1);world.NotifyChanged();nextCivilisationRefresh=0;});for(int j=deathPage*pageSize;j<Math.Min(visible.Count,(deathPage+1)*pageSize);j++)DeathDetails(parent,visible[visible.Count-1-j]);}
        void CivicSecurityContext(VisualElement parent,RtsBuilding b){var c=world.Settlements?[b.team];if(c==null)return;
            if(b.definition.id==CivilisationRuntime.Graveyard){var records=new ScrollView();records.style.maxHeight=360;parent.Add(records);RecentDeaths(records,c,8);return;}
            if(b.definition.id==CivilisationRuntime.PoliceHeadquarters||b.definition.id==CivilisationRuntime.CountyJail||b.definition.id==CivilisationRuntime.Court||b.definition.id==CivilisationRuntime.FederalPrison||b.definition.id==CivilisationRuntime.PrisonWing){Button(parent,"CRIME REPORTS & CUSTODY",()=>{inspectedFaction=b.team;OpenCrime();},"crime-building-open");if(c.crime!=null)Label(parent,$"Reported crimes {c.crime.reportedCrimes} · arrests {c.crime.arrests} · searches {c.crime.searches}","body");}
            if(b.definition.id!=CivilisationRuntime.PoliceHeadquarters)return;int staff=0;foreach(var p in c.residents)if(p.alive&&p.role==CivilianRole.Officer)staff++;Label(parent,$"Patrol officers requested {c.security.requestedPatrols} · employed {staff}\nCivilian zombie deaths: today {c.security.civilianDeathsToday} · yesterday {c.security.civilianDeathsYesterday}","body");
            bool control=!Observer&&b.team==0;var row=new VisualElement();row.AddToClassList("row");parent.Add(row);Button(row,"FEWER PATROLS",()=>{c.security.automaticPatrols=false;c.security.requestedPatrols=Math.Max(0,c.security.requestedPatrols-1);world.NotifyChanged();}).SetEnabled(control);Button(row,"MORE PATROLS",()=>{c.security.requestedPatrols=Math.Min(32,c.security.requestedPatrols+1);world.NotifyChanged();}).SetEnabled(control);Button(parent,"AUTOMATIC PATROLS: "+(c.security.automaticPatrols?"ON":"OFF"),()=>{c.security.automaticPatrols=!c.security.automaticPatrols;world.NotifyChanged();}).SetEnabled(control);
            Label(parent,"PATROL CIRCUIT · connected road entrances","subheading");var names=new List<string>();var ids=new List<long>();foreach(var target in world.Buildings)if(target.team==b.team&&!target.removed&&target.Complete&&world.Roads.Connected(b,target)){names.Add(target.definition.name+" #"+target.persistentId);ids.Add(target.persistentId);}
            if(names.Count>0){var choice=new DropdownField("Add patrol stop",names,0);parent.Add(choice);Button(parent,"ADD STOP",()=>{if(c.security.patrolStops.Count<8)c.security.patrolStops.Add(ids[choice.index]);world.NotifyChanged();}).SetEnabled(control&&c.security.patrolStops.Count<8);}
            for(int i=0;i<c.security.patrolStops.Count;i++){int stop=i;var target=world.FindBuilding(c.security.patrolStops[i]);Button(parent,$"{i+1}. {target?.definition.name??"Missing entrance"} · REMOVE",()=>{c.security.patrolStops.RemoveAt(stop);world.NotifyChanged();}).SetEnabled(control);}
        }
    }
}
